-- =====================================================================
-- Hoops Archive -- migration 0003 : ajout de 7 sets Topps NBA 2025-26
-- FICHIER GENERE AUTOMATIQUEMENT -- ne pas editer a la main.
-- Sources : data/2025-26-topps-basketball.json, -holiday.json, -chrome.json,
--           -chrome-sapphire.json, -midnight.json, -finest.json, -three.json
-- Relancable sans risque (ON CONFLICT DO UPDATE).
-- =====================================================================

begin;

-- 1. Les sets
on conflict (id) do update set
  name = excluded.name,
  manufacturer = excluded.manufacturer,
  release_date = excluded.release_date,
  base_count = excluded.base_count;

-- 2. Les sous-ensembles (191)
on conflict (set_id, id) do update set
  name = excluded.name,
  type = excluded.type;

-- 3. Les cartes (6982 numeros uniques)
on conflict (set_id, card_code) do update set
  subset = excluded.subset,
  player = excluded.player,
  team = excluded.team,
  player_id = excluded.player_id,
  team_id = excluded.team_id,
  season = excluded.season,
  rookie = excluded.rookie,
  variant = excluded.variant,
  jersey_number = excluded.jersey_number;

-- 4. Associations carte/joueur (7071)
on conflict (set_id, card_code, slot) do update set
  player = excluded.player,
  player_id = excluded.player_id,
  team = excluded.team,
  team_id = excluded.team_id,
  season = excluded.season;

commit;
